// Determine if fix is verified based on re-audit result
const fix = $('Split: One Item per Fix').first().json;
const audit = $json; // re-audit result

let verified = false;
let reason = 'unknown';

const fixType = fix.fix_type;

if (fixType === 'schema_injection') {
  // Check if schema score improved
  verified = (audit.scores && audit.scores.schema >= 70);
  reason = verified ? 'Schema score >= 70' : `Schema score = ${audit.scores?.schema}`;
} else if (fixType === 'llmstxt') {
  // Check no llmstxt finding in critical/high
  const llmsFindings = (audit.findings || []).filter(f => f.category === 'llmstxt' && ['critical','high'].includes(f.severity));
  verified = llmsFindings.length === 0;
  reason = verified ? 'No critical/high llmstxt findings' : 'llmstxt findings still present';
} else if (fixType === 'robots') {
  // Check crawler score
  verified = (audit.scores && audit.scores.crawlers >= 60);
  reason = verified ? 'Crawlers score >= 60' : `Crawlers score = ${audit.scores?.crawlers}`;
} else if (fixType === 'meta') {
  // Check content score improved
  verified = (audit.scores && audit.scores.content >= 40);
  reason = verified ? 'Content score >= 40' : `Content score = ${audit.scores?.content}`;
} else {
  // Default: overall score improved
  verified = (audit.scores && audit.scores.overall >= 40);
  reason = `Overall score = ${audit.scores?.overall}`;
}

return [{ json: { fix_id: fix.id, verified, reason, new_scores: audit.scores } }];
